35	/** Rounds up to whole G (the MHPCO's favour), ignoring binary floating-point noise. */
36	const roundUpToWholeG = (amount: number): number => Math.ceil(Number(amount.toFixed(6)));
37	
38	const BASE_PREMIUM: Record<string, number> = {
39	  sword: 100,
40	  amulet: 60,
41	  staff: 80,
42	  potion: 40,
43	  rune: 25,
44	  moonstone: 25,
45	};
46	
47	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
48	const POLICY_FEE = 5;
49	
50	const COMPONENT_TYPES = ["rune", "moonstone"];
51	const BUILDING_BLOCK_SIZE = 3;
52	const BUILDING_BLOCK_BASE_PREMIUM = 60;
53	
54	const isComponent = (item: Item): boolean => COMPONENT_TYPES.includes(item.type);
55	
56	const sum = (amounts: number[]): number => amounts.reduce((a, b) => a + b, 0);
57	
58	const countOfType = (items: Item[], type: string): number =>
59	  items.filter((item) => item.type === type).length;
60	
61	/**
62	 * Components of one kind are bundled into building blocks of 3, each charged at
63	 * the special block rate; leftovers are charged individually.
64	 */
65	const componentGroupBasePremium = (type: string, count: number): number => {
66	  const blocks = Math.floor(count / BUILDING_BLOCK_SIZE);
67	  const singles = count % BUILDING_BLOCK_SIZE;
68	  return blocks * BUILDING_BLOCK_BASE_PREMIUM + singles * BASE_PREMIUM[type];
69	};
70	
71	const CURSED_SURCHARGE_RATE = 0.5;
72	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
73	const HIGH_ENCHANTMENT_LEVEL = 5;
74	
75	const surchargeFactor = (applies: boolean, rate: number): number => (applies ? 1 + rate : 1);
76	
77	const isCursed = (item: Item): boolean => item.cursed === true;
78	const isHighlyEnchanted = (item: Item): boolean =>
79	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
80	
81	/** Risk surcharges attach to the individual item that carries the risk, and compound. */
82	const riskMultiplierOf = (item: Item): number =>
83	  surchargeFactor(isCursed(item), CURSED_SURCHARGE_RATE) *
84	  surchargeFactor(isHighlyEnchanted(item), HIGH_ENCHANTMENT_SURCHARGE_RATE);
85	
86	/** Main items are priced one by one off the base price list, each carrying its own risk load. */
87	const mainItemsPremium = (items: Item[]): number =>
88	  sum(
89	    items
90	      .filter((item) => !isComponent(item))
91	      .map((item) => BASE_PREMIUM[item.type] * riskMultiplierOf(item)),
92	  );
93	
94	/**
95	 * Components are priced per kind, so alike ones can bundle into building blocks.
96	 * Pricing by count means individual risk flags are not visible here — no test covers
97	 * a cursed component yet, so this stays as-is rather than being fixed speculatively.
98	 */
99	const componentsPremium = (items: Item[]): number =>
100	  sum(COMPONENT_TYPES.map((type) => componentGroupBasePremium(type, countOfType(items, type))));
101	
102	/** Base price list plus per-item risk loading — everything before customer-level modifiers. */
103	const riskLoadedPremiumOf = (items: Item[]): number =>
104	  mainItemsPremium(items) + componentsPremium(items);
105	
106	const quote = (items: Item[]): QuoteResult => {
107	  const riskLoadedPremium = riskLoadedPremiumOf(items);
108	  const withFirstInsuranceSurcharge = riskLoadedPremium * (1 + FIRST_INSURANCE_SURCHARGE_RATE);
109	  return { premium: roundUpToWholeG(withFirstInsuranceSurcharge) + POLICY_FEE };
110	};
111	
112	export const runScenario = (scenario: Scenario): ScenarioOutcome => {
113	  const results = scenario.steps.map((step) => {
114	    if (step.op === "quote") return quote(step.items);
115	    throw new Error("claim steps are not implemented yet");
116	  });
117	  return { results };
118	};
